function normalizeRecord(json) {
  if (!json) return null;

  if (Array.isArray(json.records)) {
    return json.records.map(normalizeRecord).filter(Boolean);
  }

  if (json.fields) {
    return {
      id: json.id || json.recordId,
      fields: json.fields,
    };
  }

  const { id, recordId, createdTime, ...rest } = json;

  return {
    id: id || recordId,
    fields: rest,
  };
}

function getRecords(nodeName) {
  const items = $items(nodeName) || [];
  const records = [];

  for (const item of items) {
    const normalized = normalizeRecord(item.json);

    if (Array.isArray(normalized)) {
      records.push(...normalized);
    } else if (normalized) {
      records.push(normalized);
    }
  }

  return records.filter((record) => record.id);
}

function asLinks(value) {
  if (!value) return [];

  if (Array.isArray(value)) {
    return value
      .map((item) => {
        if (typeof item === "string") return item;
        if (item?.id) return item.id;
        if (item?.recordId) return item.recordId;
        return String(item || "");
      })
      .map((item) => item.trim())
      .filter(Boolean);
  }

  if (typeof value === "string") {
    return [value.trim()].filter(Boolean);
  }

  return [];
}

function getString(value) {
  return String(value || "").trim();
}

function getNumber(value) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : null;
}

function normalize(value) {
  return getString(value)
    .toLowerCase()
    .replaceAll("ı", "i")
    .replaceAll("ğ", "g")
    .replaceAll("ü", "u")
    .replaceAll("ş", "s")
    .replaceAll("ö", "o")
    .replaceAll("ç", "c")
    .trim();
}

function isPresent(value) {
  const status = normalize(value);
  return status === "geldi" || status === "gec geldi" || status === "geç geldi";
}

function average(numbers) {
  const valid = numbers.filter((value) => value !== null && Number.isFinite(value));
  if (valid.length === 0) return null;

  return Math.round(
    (valid.reduce((sum, value) => sum + value, 0) / valid.length) * 100,
  ) / 100;
}

function getWeekKey() {
  const now = new Date();
  const year = now.getFullYear();

  const start = new Date(year, 0, 1);
  const days = Math.floor((now - start) / (24 * 60 * 60 * 1000));
  const week = Math.ceil((days + start.getDay() + 1) / 7);

  return `${year}-H${String(week).padStart(2, "0")}`;
}

function trendFromGrades(grades) {
  if (grades.length < 2) return "Veri Yetersiz";

  const sorted = [...grades].sort((a, b) => {
    const aTime = new Date(a.date || "2000-01-01").getTime();
    const bTime = new Date(b.date || "2000-01-01").getTime();
    return aTime - bTime;
  });

  const recent = sorted.slice(-3);
  const older = sorted.slice(0, Math.max(sorted.length - 3, 1));

  const recentAvg = average(recent.map((item) => item.score));
  const olderAvg = average(older.map((item) => item.score));

  if (recentAvg === null || olderAvg === null) return "Veri Yetersiz";

  if (recentAvg >= olderAvg + 5) return "Yükseliyor";
  if (recentAvg <= olderAvg - 5) return "Düşüyor";
  return "Sabit";
}

function riskLevelFromScore(score) {
  if (score >= 80) return "Kritik";
  if (score >= 60) return "Yüksek";
  if (score >= 35) return "Orta";
  return "Düşük";
}

function calculateRiskScore({
  gradeAverage,
  attendanceAbsenceRate,
  assignmentDeliveryRate,
  lateSubmissionCount,
  latestPredictionRisk,
}) {
  let score = 0;

  if (gradeAverage === null) score += 15;
  else if (gradeAverage < 50) score += 45;
  else if (gradeAverage < 65) score += 25;
  else if (gradeAverage < 75) score += 10;

  if (attendanceAbsenceRate !== null) {
    if (attendanceAbsenceRate >= 40) score += 30;
    else if (attendanceAbsenceRate >= 25) score += 20;
    else if (attendanceAbsenceRate >= 15) score += 10;
  }

  if (assignmentDeliveryRate !== null) {
    if (assignmentDeliveryRate < 50) score += 25;
    else if (assignmentDeliveryRate < 75) score += 15;
    else if (assignmentDeliveryRate < 90) score += 8;
  }

  if (lateSubmissionCount >= 3) score += 15;
  else if (lateSubmissionCount >= 1) score += 8;

  const normalizedPredictionRisk = normalize(latestPredictionRisk);

  if (normalizedPredictionRisk === "kritik") score += 25;
  else if (normalizedPredictionRisk === "yuksek") score += 18;
  else if (normalizedPredictionRisk === "orta") score += 8;

  return Math.min(100, Math.max(0, Math.round(score)));
}

const memberships = getRecords("GET Active Memberships");
const users = getRecords("GET Users");
const classes = getRecords("GET Classes");
const grades = getRecords("GET Published Grades");
const assignments = getRecords("GET Assignments");
const submissions = getRecords("GET Submissions");
const attendanceRecords = getRecords("GET Attendance Records");
const predictions = getRecords("GET Predictions");
const existingSummaries = getRecords("GET Existing Student Summaries");

const weekKey = getWeekKey();
const today = new Date().toISOString().slice(0, 10);

const existingSummaryNames = existingSummaries
  .map((summary) => getString(summary.fields.Ozet_Adi))
  .join("\n");

const output = [];

for (const membership of memberships) {
  const studentId = asLinks(membership.fields.Kullanici)[0];
  const classId = asLinks(membership.fields.Sinif)[0];

  if (!studentId || !classId) continue;

  const student = users.find((user) => user.id === studentId);
  const classRecord = classes.find((item) => item.id === classId);

  if (!student || !classRecord) continue;

  const studentName = getString(student.fields.Ad_Soyad) || "Öğrenci";
  const studentEmail = getString(student.fields.Eposta);
  const className =
    getString(classRecord.fields.Sinif_Adi) ||
    getString(classRecord.fields.Ders_Adi) ||
    "Sınıf";

  const summaryName = `${studentName} - ${className} - Haftalık Özet - ${weekKey}`;

  if (existingSummaryNames.includes(summaryName)) {
    continue;
  }

  const studentGrades = grades
    .filter((grade) => {
      const gradeStudentId = asLinks(grade.fields.Ogrenci)[0];
      const gradeClassId = asLinks(grade.fields.Sinif)[0];
      return gradeStudentId === studentId && gradeClassId === classId;
    })
    .map((grade) => ({
      id: grade.id,
      type: getString(grade.fields.Not_Turu),
      score: getNumber(grade.fields.Puan),
      maxPoint: getNumber(grade.fields.Maksimum_Puan) || 100,
      date: getString(grade.fields.Tarih || grade.fields.Yayin_Tarihi),
    }))
    .filter((grade) => grade.score !== null);

  const gradeAverage = average(studentGrades.map((grade) => grade.score));
  const lastThreeGradeAverage = average(
    [...studentGrades]
      .sort((a, b) => {
        const aTime = new Date(a.date || "2000-01-01").getTime();
        const bTime = new Date(b.date || "2000-01-01").getTime();
        return bTime - aTime;
      })
      .slice(0, 3)
      .map((grade) => grade.score),
  );

  const gradeTrend = trendFromGrades(studentGrades);

  const classAssignments = assignments.filter((assignment) =>
    asLinks(assignment.fields.Sinif).includes(classId),
  );

  const studentSubmissions = submissions.filter((submission) => {
    const submissionStudentId = asLinks(submission.fields.Ogrenci)[0];
    const submissionClassId = asLinks(submission.fields.Sinif)[0];
    return submissionStudentId === studentId && submissionClassId === classId;
  });

  const deliveryRate =
    classAssignments.length > 0
      ? Math.round((studentSubmissions.length / classAssignments.length) * 10000) / 100
      : null;

  const missingAssignmentCount =
    classAssignments.length > 0
      ? Math.max(classAssignments.length - studentSubmissions.length, 0)
      : 0;

  const lateSubmissionCount = studentSubmissions.filter((submission) =>
    Boolean(submission.fields.Gec_Mi),
  ).length;

  const studentAttendance = attendanceRecords.filter((attendance) => {
    const attendanceStudentId = asLinks(attendance.fields.Ogrenci)[0];
    const attendanceClassId = asLinks(attendance.fields.Sinif)[0];
    return attendanceStudentId === studentId && attendanceClassId === classId;
  });

  const presentCount = studentAttendance.filter((attendance) =>
    isPresent(attendance.fields.Durum),
  ).length;

  const absenceRate =
    studentAttendance.length > 0
      ? Math.round(((studentAttendance.length - presentCount) / studentAttendance.length) * 10000) / 100
      : null;

  const classGrades = grades
    .filter((grade) => asLinks(grade.fields.Sinif).includes(classId))
    .map((grade) => getNumber(grade.fields.Puan))
    .filter((value) => value !== null);

  const classAverage = average(classGrades);

  const studentPredictions = predictions
    .filter((prediction) => {
      const predictionStudentId = asLinks(prediction.fields.Ogrenci)[0];
      const predictionClassId = asLinks(prediction.fields.Sinif)[0];
      return predictionStudentId === studentId && predictionClassId === classId;
    })
    .sort((a, b) => {
      const aTime = new Date(a.fields.Tahmin_Tarihi || a.createdTime || "2000-01-01").getTime();
      const bTime = new Date(b.fields.Tahmin_Tarihi || b.createdTime || "2000-01-01").getTime();
      return bTime - aTime;
    });

  const latestPrediction = studentPredictions[0];
  const latestPredictionRisk = getString(latestPrediction?.fields?.Risk_Seviyesi);
  const latestPredictionText =
    getString(latestPrediction?.fields?.Ozet) ||
    getString(latestPrediction?.fields?.Ogretmene_Gosterilecek) ||
    "";

  const riskScore = calculateRiskScore({
    gradeAverage,
    attendanceAbsenceRate: absenceRate,
    assignmentDeliveryRate: deliveryRate,
    lateSubmissionCount,
    latestPredictionRisk,
  });

  const riskLevel = riskLevelFromScore(riskScore);

  const gradeStatusScore =
    gradeAverage === null
      ? null
      : Math.round((gradeAverage / 100) * 100) / 100;

  const dataSummary = [
    `Öğrenci: ${studentName}`,
    `Sınıf: ${className}`,
    `Hafta: ${weekKey}`,
    `Genel ortalama: ${gradeAverage === null ? "Yok" : gradeAverage}`,
    `Son 3 not ortalaması: ${lastThreeGradeAverage === null ? "Yok" : lastThreeGradeAverage}`,
    `Not trendi: ${gradeTrend}`,
    `Devamsızlık oranı: ${absenceRate === null ? "Yok" : `${absenceRate}%`}`,
    `Ödev teslim oranı: ${deliveryRate === null ? "Yok" : `${deliveryRate}%`}`,
    `Geç teslim sayısı: ${lateSubmissionCount}`,
    `Eksik ödev sayısı: ${missingAssignmentCount}`,
    `Sınıf ortalaması: ${classAverage === null ? "Yok" : classAverage}`,
    `Risk puanı: ${riskScore}`,
    `Risk seviyesi: ${riskLevel}`,
    `Son AI tahmin özeti: ${latestPredictionText || "Yok"}`,
  ].join("\n");

  const aiPrompt = `
Sen AkıllıSınıf AI sisteminde çalışan öğrenci gelişim özeti motorusun.

Aşağıdaki haftalık verilere göre öğrenciye ve öğretmene uygun, destekleyici Türkçe gelişim özeti üret.

Veriler:
${dataSummary}

Kurallar:
- Sadece geçerli JSON döndür.
- Markdown kullanma.
- Dil Türkçe olsun.
- Öğrenciyi suçlayıcı dil kullanma.
- Kısa, net ve uygulanabilir öneriler ver.
- Risk seviyesi şu değerlerden biri olsun: Düşük, Orta, Yüksek, Kritik.

JSON formatı:
{
  "ai_onerisi": "öğrenciye yönelik kısa öneri metni",
  "ogretmen_notu": "öğretmene yönelik kısa takip notu",
  "guclu_yon": "öğrencinin olumlu tarafı",
  "gelisim_alani": "geliştirmesi gereken alan",
  "risk_seviyesi": "Orta"
}
`;

  output.push({
    json: {
      weekKey,
      today,
      summaryName,
      studentId,
      classId,
      membershipId: membership.id,
      studentName,
      studentEmail,
      className,
      gradeAverage,
      lastThreeGradeAverage,
      gradeTrend,
      gradeStatusScore,
      absenceRate,
      deliveryRate,
      lateSubmissionCount,
      missingAssignmentCount,
      classAverage,
      riskScore,
      riskLevel,
      latestPredictionId: latestPrediction?.id || "",
      dataSummary,
      aiPrompt,
    },
  });
}

return output;

