function getString(value) {
  return String(value || "").trim();
}

function getNumberOrNull(value) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : null;
}

function stripJsonFence(text) {
  return getString(text)
    .replace(/^```json/i, "")
    .replace(/^```/i, "")
    .replace(/```$/i, "")
    .trim();
}

function parseAiJson(text) {
  const clean = stripJsonFence(text);

  try {
    return JSON.parse(clean);
  } catch {
    const match = clean.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        return JSON.parse(match[0]);
      } catch {
        return null;
      }
    }

    return null;
  }
}

function formatPercentForAirtable(value) {
  const numberValue = getNumberOrNull(value);

  if (numberValue === null) return null;

  // Airtable percent fields usually expect 0.85 to show 85%.
  return numberValue / 100;
}

function buildEmailHtml({
  studentName,
  className,
  weekKey,
  riskLevel,
  aiAdvice,
  gradeAverage,
  deliveryRate,
  absenceRate,
}) {
  return `
<div style="font-family:Arial,Helvetica,sans-serif;background:#f1f5f9;padding:32px;">
  <div style="max-width:680px;margin:auto;background:white;border-radius:24px;overflow:hidden;border:1px solid #e2e8f0;">
    <div style="background:#0f172a;color:white;padding:28px 32px;">
      <div style="font-size:12px;letter-spacing:4px;text-transform:uppercase;color:#bfdbfe;font-weight:700;">
        AkıllıSınıf AI
      </div>
      <h1 style="margin:12px 0 0;font-size:28px;line-height:1.2;color:#ffffff;">
        Haftalık Gelişim Özetiniz
      </h1>
      <p style="margin:12px 0 0;color:#dbeafe;font-size:15px;line-height:1.6;">
        Bu özet, haftalık akademik verilerinize göre otomatik oluşturulmuştur.
      </p>
    </div>

    <div style="padding:32px;color:#0f172a;">
      <p style="margin:0 0 16px;font-size:16px;line-height:1.7;">
        Merhaba <strong>${studentName}</strong>,
      </p>

      <p style="margin:0 0 20px;font-size:16px;line-height:1.7;">
        <strong>${className}</strong> sınıfı için <strong>${weekKey}</strong> haftasına ait gelişim özetiniz hazırlandı.
      </p>

      <div style="margin:22px 0;padding:18px;border-radius:18px;background:#eff6ff;border:1px solid #bfdbfe;">
        <p style="margin:0;color:#1d4ed8;font-size:12px;text-transform:uppercase;font-weight:700;letter-spacing:1px;">
          AI Önerisi
        </p>
        <p style="margin:8px 0 0;font-size:16px;font-weight:600;color:#1e3a8a;line-height:1.6;">
          ${aiAdvice}
        </p>
      </div>

      <table style="width:100%;border-collapse:collapse;margin-top:18px;border:1px solid #e2e8f0;">
        <tr>
          <td style="padding:12px;font-weight:700;color:#475569;">Genel Ortalama</td>
          <td style="padding:12px;color:#0f172a;">${gradeAverage === null ? "-" : gradeAverage}</td>
        </tr>
        <tr>
          <td style="padding:12px;font-weight:700;color:#475569;">Ödev Teslim Oranı</td>
          <td style="padding:12px;color:#0f172a;">${deliveryRate === null ? "-" : deliveryRate + "%"}</td>
        </tr>
        <tr>
          <td style="padding:12px;font-weight:700;color:#475569;">Devamsızlık Oranı</td>
          <td style="padding:12px;color:#0f172a;">${absenceRate === null ? "-" : absenceRate + "%"}</td>
        </tr>
        <tr>
          <td style="padding:12px;font-weight:700;color:#475569;">Risk Seviyesi</td>
          <td style="padding:12px;color:#0f172a;">${riskLevel}</td>
        </tr>
      </table>

      <p style="margin:22px 0 0;font-size:15px;line-height:1.7;color:#475569;">
        Detaylı gelişim bilgilerinizi AkıllıSınıf AI öğrenci panelinden inceleyebilirsiniz.
      </p>
    </div>

    <div style="background:#f8fafc;padding:20px 32px;border-top:1px solid #e2e8f0;color:#64748b;font-size:12px;line-height:1.6;">
      AkıllıSınıf AI · Yapay Zekâ Destekli Sınıf Performans ve Erken Uyarı Sistemi
    </div>
  </div>
</div>
`;
}

const inputItems = $items("Prepare Weekly Student Summaries");
const aiItems = $items("OpenRouter Weekly Summary");

const output = [];

for (let index = 0; index < aiItems.length; index += 1) {
  const source = inputItems[index]?.json || {};
  const aiResponse = aiItems[index]?.json || {};

  const aiText =
    aiResponse.choices?.[0]?.message?.content ||
    aiResponse.body?.choices?.[0]?.message?.content ||
    "";

  const parsed = parseAiJson(aiText) || {};

  const aiAdvice =
    getString(parsed.ai_onerisi) ||
    "Bu hafta düzenli tekrar yapmanız ve eksik konuları küçük parçalara bölerek çalışmanız önerilir.";

  const teacherNote =
    getString(parsed.ogretmen_notu) ||
    "Öğrencinin haftalık gelişimi takip edilmelidir.";

  const aiRiskLevel = getString(parsed.risk_seviyesi) || source.riskLevel || "Orta";

  const finalAiRecommendation = [
    aiAdvice,
    "",
    "Güçlü yön:",
    getString(parsed.guclu_yon) || "-",
    "",
    "Gelişim alanı:",
    getString(parsed.gelisim_alani) || "-",
    "",
    "Öğretmen takip notu:",
    teacherNote,
  ].join("\n");

  const fields = {
    Ozet_Adi: source.summaryName,
    Ogrenci: [source.studentId],
    Sinif: [source.classId],
    Uyelik: [source.membershipId],
    Not_Trendi: source.gradeTrend,
    Gec_Teslim_Sayisi: source.lateSubmissionCount,
    Eksik_Odev_Sayisi: source.missingAssignmentCount,
    Risk_Puani: source.riskScore,
    Risk_Seviyesi: aiRiskLevel,
    AI_Onerisi: finalAiRecommendation,
    Son_Hesaplama_Tarihi: source.today,
  };

  if (source.gradeAverage !== null) fields.Genel_Ortalama = source.gradeAverage;
  if (source.lastThreeGradeAverage !== null) fields.Son_3_Not_Ortalamasi = source.lastThreeGradeAverage;
  if (source.gradeStatusScore !== null) fields.Not_Dususu_Puani = source.gradeStatusScore;
  if (source.absenceRate !== null) fields.Devamsizlik_Orani = formatPercentForAirtable(source.absenceRate);
  if (source.deliveryRate !== null) fields.Odev_Teslim_Orani = formatPercentForAirtable(source.deliveryRate);
  if (source.classAverage !== null && source.gradeAverage !== null) {
  fields.Sinif_Ortalamasina_Gore_Fark =
    Math.round((source.gradeAverage - source.classAverage) * 100) / 100;
}
  if (source.latestPredictionId) fields.Tahminler = [source.latestPredictionId];

  output.push({
    json: {
      fields,
      emailTo: source.studentEmail,
      emailSubject: `Haftalık gelişim özetiniz hazır: ${source.className}`,
      emailHtml: buildEmailHtml({
        studentName: source.studentName,
        className: source.className,
        weekKey: source.weekKey,
        riskLevel: aiRiskLevel,
        aiAdvice,
        gradeAverage: source.gradeAverage,
        deliveryRate: source.deliveryRate,
        absenceRate: source.absenceRate,
      }),
      notificationFields: {
        Bildirim_Basligi: "Haftalık gelişim özeti hazır",
        Alici: [source.studentId],
        Sinif: [source.classId],
        Bildirim_Turu: "Haftalık Özet",
        Mesaj:
          `Merhaba ${source.studentName}, ${source.className} sınıfı için haftalık gelişim özetiniz hazırlandı. ` +
          `Risk seviyesi: ${aiRiskLevel}. AI önerisi: ${aiAdvice}`,
        Onem_Derecesi: aiRiskLevel === "Yüksek" || aiRiskLevel === "Kritik" ? "Yüksek" : "Orta",
        Okundu_Mu: false,
        Gonderildi_Mi: true,
        Kanal: "E-posta + Webhook",
      },
    },
  });
}

return output;
